async function prepareReceiptEditor(expense){resetReceiptEditor();currentReceipt=expense?.receipt||null;if(!currentReceipt)return;const expenseId=expense.id;$("#receipt-status").textContent="Loading receipt…";try{let dataUrl=currentReceipt.dataUrl;if(!dataUrl&&currentReceipt.documentId&&firebaseStore)dataUrl=await firebaseStore.getReceiptData(currentGroup().id,currentReceipt.documentId);if(editingExpenseId!==expenseId)return;if(!dataUrl)throw new Error("The receipt image is missing.");showReceiptPreview(dataUrl,`Receipt for ${expense.description}`);$("#receipt-status").textContent=currentReceipt.name||"Receipt attached."}catch(error){if(editingExpenseId===expenseId)$("#receipt-status").textContent="Receipt preview is unavailable."}}
