function normalizeGroups(groups){return (groups||[]).map(group=>{group.visibility=group.visibility==="public"?"public":"private";group.currency=normalizeCurrency(group.currency);group.expenses=group.expenses||[];group.deletedExpenses=group.deletedExpenses||[];group.payments=group.payments||[];group.settlementAdjustments=Array.isArray(group.settlementAdjustments)?group.settlementAdjustments.map(adjustment=>({...adjustment,entries:(adjustment.entries||[]).filter(entry=>group.members.some(member=>member.id===entry.memberId)&&Number.isFinite(Number(entry.amount))).map(entry=>({...entry,currency:normalizeCurrency(entry.currency||group.currency),amount:Number(entry.amount)}))})):[];group.testOffset=group.testOffset||0;if(group.settlementConversion&&SUPPORTED_CURRENCIES.includes(group.settlementConversion.targetCurrency)){const targetCurrency=normalizeCurrency(group.settlementConversion.targetCurrency),rates={[targetCurrency]:1};Object.entries(group.settlementConversion.rates||{}).forEach(([currency,rate])=>{const number=Number(rate);if(SUPPORTED_CURRENCIES.includes(currency)&&Number.isFinite(number)&&number>0)rates[currency]=number});group.settlementConversion={...group.settlementConversion,targetCurrency,rates}}else delete group.settlementConversion;[...group.expenses,...group.deletedExpenses].forEach(expense=>{expense.currency=normalizeCurrency(expense.currency||group.currency);if(!expense.shares&&expense.participantIds?.length){const base=Math.floor(expense.amount/expense.participantIds.length),remainder=expense.amount-base*expense.participantIds.length;expense.shares=expense.participantIds.map((id,index)=>({id,amount:base+(index<remainder?1:0)}))}expense.payers=expensePayers(expense);expense.payerId=expense.payers[0]?.id||expense.payerId||null});group.payments.forEach(payment=>payment.currency=normalizeCurrency(payment.currency||group.currency));return group})}
